const text = $input.first().json.text || "";

return [{
  json: {
    text,
    textLength: text.length
  }
}];

// 1. Extract the raw text from the Groq API response
let rawText = "";
const inputData = $input.item.json;

// Look specifically for the Groq/OpenAI JSON structure
if (inputData.choices && inputData.choices.length > 0 && inputData.choices[0].message) {
    rawText = inputData.choices[0].message.content;
} else if (typeof inputData.text === 'string') {
    rawText = inputData.text;
} else if (inputData.message && typeof inputData.message.content === 'string') {
    rawText = inputData.message.content;
} else {
    rawText = JSON.stringify(inputData);
}

// 2. Clean up Markdown wrappers (```json ... ```) if they exist
if (rawText.includes("```json")) {
    rawText = rawText.split("```json")[1].split("```")[0];
} else if (rawText.includes("```")) {
    rawText = rawText.split("```")[1].split("```")[0];
}

// 3. Parse the clean string into a real JavaScript Object
let data = {};
try {
    data = JSON.parse(rawText.trim());
} catch (e) {
    // If parsing fails, throw an error to see it clearly in the n8n logs
    throw new Error("Failed to parse AI output into JSON: " + rawText);
}

// 4. Extract arrays safely
const behavioralQs = data.behavioral_questions || [];
const projectQs = data.project_questions || [];
const technicalQs = data.technical_questions || [];

// 5. Flatten everything into a single array of purely STRINGS
const flatQuestions = [
    ...behavioralQs, // Already strings
    ...projectQs.map(item => item.question),  // Extract the "question" string from the object
    ...technicalQs.map(item => item.question) // Extract the "question" string from the object
].filter(q => q !== undefined && q !== null); // Filter out any empty items

// 6. Safely generate or extract a Session ID
let sessionId = "session_" + $execution.id; 
try {
    // Note: Assuming your webhook node is named 'Webhook1' based on earlier logs
    const webhookData = $('Webhook1').first().json; 
    if (webhookData && webhookData.body && webhookData.body.session_id) {
        sessionId = webhookData.body.session_id;
    }
} catch (error) {
    // Failsafe fallback if Webhook node isn't found
}

// 7. Output the fully completed payload for the database (Supabase)
return {
  session_id: sessionId,
  questions: flatQuestions,
  current_index: 0,
  total_questions: flatQuestions.length,
  answers: []
};

const dbRow = $('Get a row').item.json;

return {
  session_id: dbRow.session_id,
  question_to_ask: dbRow.questions[0], // Grabs the first question
  next_index: 1,
  updated_answers: []
};

