// 1. Get the Database row safely
const dbRow = $('Get a row').item.json;

// 2. Grab the transcript safely (Prevents crashes if Groq Whisper fails)
let realTranscript = "[Audio received, but transcription failed]";
try {
    const sttItem = $('STT').item.json;
    if (sttItem && sttItem.text) {
        realTranscript = sttItem.text;
    }
} catch (error) {
    console.log("STT failed or was skipped.");
}

// 3. Append the transcript to the existing answers array
let currentAnswers = dbRow.answers || [];
currentAnswers.push(realTranscript);

let currentIndex = dbRow.current_index || 0;
// Fallback in case total_questions isn't set
let totalQuestions = dbRow.total_questions || dbRow.questions.length; 
let questionsArray = dbRow.questions || [];

// 4. Handle End of Interview
if (currentIndex >= totalQuestions) {
    return { 
        status: "completed", 
        session_id: dbRow.session_id,
        updated_answers: currentAnswers,
        question_to_ask: "Interview Completed.",
        next_index: currentIndex
    };
}

// 5. Extract the next question and advance the index
const nextQuestion = questionsArray[currentIndex];

return {
    session_id: dbRow.session_id,
    question_to_ask: nextQuestion,
    next_index: currentIndex + 1,
    updated_answers: currentAnswers
};

let sourceData;

try {
    // Attempt to grab data from Phase 2 (Answer Recording path)
    // .first() ensures we don't get item index mismatch errors
    sourceData = $('Code in JavaScript3').first().json;
} catch (error) {
    try {
        // If Code 3 didn't run, fallback to Phase 1.5 (Fetch Q1 path)
        sourceData = $('Code in JavaScript2').first().json;
    } catch (innerError) {
        throw new Error("Failed to find data from either Code 2 or Code 3.");
    }
}

// Reconstruct the ENTIRE object safely
let finalJson = {
    session_id: sourceData.session_id,
    next_index: sourceData.next_index,
    updated_answers: sourceData.updated_answers || [],
    question_to_ask: sourceData.question_to_ask || "",
    interview_status: sourceData.status || "in_progress",
    audio_b64: "" // Default to empty
};

// Handle the audio conversion safely
const ttsItem = $input.first();
if (ttsItem && ttsItem.binary && ttsItem.binary.data) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    finalJson.audio_b64 = buffer.toString('base64');
}

return { json: finalJson };

// 1. Grab the database row we just fetched
const currentItem = $input.first();

// 2. Reach back in time and grab the data from the Webhook
const webhookData = $('Webhook').first();

// 3. Set a strict default text path
currentItem.json.action_path = "fetch_question";

// 4. If audio actually exists, attach it AND change the text path
if (webhookData.binary && webhookData.binary.audio) {
    currentItem.binary = webhookData.binary;
    currentItem.json.action_path = "process_audio";
}

return currentItem;
